const html = "<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#f7f7f2\">\n  <title>Flashcards — English Learning</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Noto+Sans+JP:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --ink: #17201d;\n      --muted: #69726e;\n      --paper: #f7f7f2;\n      --surface: #ffffff;\n      --line: #dfe3dd;\n      --soft: #eef1eb;\n      --brand: #1c6b50;\n      --brand-dark: #12513c;\n      --brand-soft: #dff1e8;\n      --glow: rgba(223, 241, 232, .8);\n      --coral: #d95f4d;\n      --coral-soft: #f9e7e3;\n      --shadow: 0 18px 45px rgba(28, 42, 36, .08);\n      --radius: 22px;\n    }\n    :root[data-theme=\"ocean\"] { --brand: #376b8c; --brand-dark: #28536f; --brand-soft: #e0edf4; --glow: rgba(218, 235, 245, .88); }\n    :root[data-theme=\"indigo\"] { --brand: #5b5f97; --brand-dark: #454978; --brand-soft: #e8e8f4; --glow: rgba(230, 229, 246, .9); }\n    :root[data-theme=\"plum\"] { --brand: #855d78; --brand-dark: #68465c; --brand-soft: #f1e5ed; --glow: rgba(242, 225, 236, .88); }\n    :root[data-theme=\"clay\"] { --brand: #a05f49; --brand-dark: #7f4635; --brand-soft: #f5e5de; --glow: rgba(246, 226, 216, .9); }\n    :root[data-theme=\"mustard\"] { --brand: #927126; --brand-dark: #715617; --brand-soft: #f4ecd5; --glow: rgba(246, 236, 205, .9); }\n\n    * { box-sizing: border-box; }\n    html, body { margin: 0; min-height: 100%; }\n    body {\n      color: var(--ink);\n      background:\n        radial-gradient(circle at 8% 0%, var(--glow), transparent 28rem),\n        var(--paper);\n      font-family: \"DM Sans\", \"Noto Sans JP\", sans-serif;\n      -webkit-font-smoothing: antialiased;\n      overscroll-behavior-y: contain;\n    }\n    button, input, textarea { font: inherit; }\n    button { color: inherit; }\n    button, label { -webkit-tap-highlight-color: transparent; }\n    button:focus-visible, input:focus-visible, textarea:focus-visible {\n      outline: 3px solid rgba(28, 107, 80, .22);\n      outline-offset: 2px;\n    }\n    ::selection { background: #c9eadb; }\n    ::-webkit-scrollbar { width: 8px; }\n    ::-webkit-scrollbar-thumb { background: #cbd1ca; border-radius: 99px; }\n\n    #app { min-height: 100dvh; }\n    .shell { min-height: 100dvh; display: flex; flex-direction: column; }\n    .topbar {\n      position: sticky;\n      top: 0;\n      z-index: 20;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      min-height: 78px;\n      padding: 14px clamp(20px, 4vw, 56px);\n      background: rgba(247, 247, 242, .86);\n      border-bottom: 1px solid rgba(205, 212, 204, .8);\n      backdrop-filter: blur(18px);\n    }\n    .brand { display: flex; align-items: center; gap: 12px; }\n    .brand-mark {\n      display: grid;\n      place-items: center;\n      width: 38px;\n      height: 38px;\n      color: white;\n      background: var(--brand);\n      border-radius: 12px;\n      box-shadow: 0 8px 20px rgba(28, 107, 80, .2);\n      font-weight: 700;\n      transform: rotate(-3deg);\n    }\n    .brand-name { font-size: 1.18rem; font-weight: 700; letter-spacing: -.03em; }\n    .brand-sub { margin-top: 1px; color: var(--muted); font-size: .68rem; letter-spacing: .12em; text-transform: uppercase; }\n    .header-actions { display: flex; align-items: center; gap: 18px; }\n    .help-button {\n      width: 42px;\n      min-height: 42px;\n      padding: 0;\n      border-color: rgba(205, 212, 204, .9);\n      border-radius: 13px;\n      background: rgba(255, 255, 255, .72);\n      font-size: 1rem;\n    }\n    .theme-picker { position: relative; }\n    .data-menu { position: relative; }\n    .theme-picker summary,\n    .data-menu summary {\n      display: grid;\n      place-items: center;\n      width: 42px;\n      height: 42px;\n      border: 1px solid rgba(205, 212, 204, .9);\n      border-radius: 13px;\n      background: rgba(255, 255, 255, .72);\n      cursor: pointer;\n      list-style: none;\n      font-size: 1.1rem;\n      transition: background .18s ease, transform .18s ease;\n    }\n    .theme-picker summary::-webkit-details-marker,\n    .data-menu summary::-webkit-details-marker { display: none; }\n    .theme-picker summary:hover,\n    .data-menu summary:hover { background: white; transform: translateY(-1px); }\n    .theme-options {\n      position: absolute;\n      top: calc(100% + 10px);\n      right: 0;\n      z-index: 40;\n      display: flex;\n      gap: 9px;\n      padding: 12px;\n      background: rgba(255, 255, 255, .94);\n      border: 1px solid var(--line);\n      border-radius: 15px;\n      box-shadow: 0 16px 38px rgba(28, 42, 36, .15);\n      backdrop-filter: blur(16px);\n      animation: reveal .18s ease both;\n    }\n    .data-options {\n      position: absolute;\n      top: calc(100% + 10px);\n      right: 0;\n      z-index: 40;\n      display: grid;\n      width: 220px;\n      padding: 8px;\n      background: rgba(255, 255, 255, .96);\n      border: 1px solid var(--line);\n      border-radius: 15px;\n      box-shadow: 0 16px 38px rgba(28, 42, 36, .15);\n      backdrop-filter: blur(16px);\n      animation: reveal .18s ease both;\n    }\n    .data-options button {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      width: 100%;\n      min-height: 44px;\n      padding: 0 12px;\n      border: 0;\n      border-radius: 10px;\n      color: var(--ink);\n      background: transparent;\n      cursor: pointer;\n      font-size: .78rem;\n      font-weight: 700;\n      text-align: left;\n    }\n    .data-options button:hover { background: var(--soft); }\n    .theme-dot {\n      width: 20px;\n      height: 20px;\n      padding: 0;\n      border: 3px solid transparent;\n      border-radius: 50%;\n      background: var(--dot);\n      background-clip: padding-box;\n      cursor: pointer;\n      transition: transform .18s ease, border-color .18s ease;\n    }\n    .theme-dot:hover { transform: scale(1.14); }\n    .theme-dot.active { border-color: rgba(23, 32, 29, .38); transform: scale(1.12); }\n    .main {\n      width: min(1040px, 100%);\n      margin: 0 auto;\n      padding: clamp(36px, 6vw, 72px) clamp(20px, 4vw, 40px) 80px;\n    }\n    .hero {\n      display: flex;\n      align-items: end;\n      justify-content: space-between;\n      gap: 24px;\n      margin-bottom: 34px;\n    }\n    .eyebrow {\n      margin: 0 0 10px;\n      color: var(--brand);\n      font-size: .75rem;\n      font-weight: 700;\n      letter-spacing: .14em;\n      text-transform: uppercase;\n    }\n    h1, h2, h3, p { margin-top: 0; }\n    .hero h1 {\n      max-width: 650px;\n      margin-bottom: 10px;\n      font-size: clamp(2rem, 5vw, 3.6rem);\n      line-height: 1.08;\n      letter-spacing: -.055em;\n    }\n    .hero-copy { margin-bottom: 0; color: var(--muted); line-height: 1.8; }\n\n    .btn {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 9px;\n      min-height: 46px;\n      padding: 0 18px;\n      border: 1px solid transparent;\n      border-radius: 13px;\n      background: transparent;\n      cursor: pointer;\n      font-weight: 700;\n      transition: transform .18s ease, background .18s ease, border-color .18s ease, box-shadow .18s ease;\n    }\n    .btn:hover { transform: translateY(-1px); }\n    .btn:active { transform: translateY(0) scale(.98); }\n    .btn-primary {\n      color: white;\n      background: var(--brand);\n      box-shadow: 0 10px 24px rgba(28, 107, 80, .18);\n    }\n    .btn-primary:hover { background: var(--brand-dark); box-shadow: 0 13px 28px rgba(28, 107, 80, .23); }\n    .btn-secondary { background: var(--surface); border-color: var(--line); }\n    .btn-secondary:hover { background: var(--soft); }\n    .btn-ghost { color: var(--muted); }\n    .btn-ghost:hover { color: var(--ink); background: var(--soft); }\n    .btn-danger { color: var(--coral); background: var(--coral-soft); }\n    .btn-wide { width: 100%; min-height: 54px; }\n    .icon { font-size: 1.15em; line-height: 1; }\n\n    .deck-list { display: grid; gap: 18px; }\n    .deck-section { margin-top: 30px; }\n    .deck-section-head {\n      display: flex;\n      align-items: end;\n      justify-content: space-between;\n      gap: 16px;\n      margin-bottom: 14px;\n      padding: 0 4px;\n    }\n    .deck-section-head h2 { margin: 0; font-size: 1.05rem; letter-spacing: -.02em; }\n    .deck-section-head p { margin: 0; color: var(--muted); font-size: .78rem; }\n    .deck {\n      overflow: hidden;\n      background: rgba(255, 255, 255, .92);\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      box-shadow: 0 4px 16px rgba(28, 42, 36, .035);\n      transition: border-color .2s ease, box-shadow .2s ease, transform .2s ease;\n    }\n    .deck:hover { border-color: #cbd3ca; box-shadow: var(--shadow); transform: translateY(-2px); }\n    .deck-main {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) auto;\n      align-items: center;\n      gap: 26px;\n      padding: 24px 26px;\n    }\n    .deck-summary {\n      display: grid;\n      grid-template-columns: 72px minmax(0, 1fr);\n      align-items: center;\n      gap: 18px;\n      min-width: 0;\n      cursor: pointer;\n    }\n    .deck-summary-body { min-width: 0; }\n    .deck-icon {\n      position: relative;\n      width: 68px;\n      height: 58px;\n    }\n    .deck-icon-card {\n      position: absolute;\n      inset: 6px 5px 4px 9px;\n      border: 1px solid color-mix(in srgb, var(--brand) 28%, var(--line));\n      border-radius: 12px;\n      background: white;\n      box-shadow: 0 7px 15px rgba(28, 42, 36, .09);\n    }\n    .deck-icon-card:first-child {\n      transform: rotate(-7deg) translate(-4px, 2px);\n      background: var(--brand-soft);\n    }\n    .deck-icon-card:last-child {\n      display: grid;\n      place-items: center;\n      color: var(--brand-dark);\n      font-size: 1.12rem;\n      font-weight: 700;\n      transform: rotate(3deg) translate(4px, -1px);\n    }\n    .deck-title-row { display: flex; align-items: center; gap: 12px; }\n    .deck h2 {\n      overflow: hidden;\n      margin-bottom: 8px;\n      font-size: 1.32rem;\n      letter-spacing: -.025em;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n    .count-pill {\n      flex: none;\n      padding: 4px 8px;\n      color: var(--muted);\n      background: var(--soft);\n      border-radius: 99px;\n      font-size: .7rem;\n      font-weight: 700;\n    }\n    .deck-meta { display: flex; justify-content: space-between; margin-bottom: 10px; color: var(--muted); font-size: .78rem; }\n    .progress { height: 6px; overflow: hidden; background: var(--soft); border-radius: 99px; }\n    .progress > span { display: block; height: 100%; background: var(--brand); border-radius: inherit; transition: width .4s ease; }\n    .deck-actions { display: flex; gap: 8px; }\n    .deck-setup { padding: 0 26px 26px; animation: reveal .24s ease both; }\n    .setup-panel { padding: 24px; background: #f5f7f2; border: 1px solid var(--line); border-radius: 17px; }\n    @keyframes reveal { from { opacity: 0; transform: translateY(-7px); } }\n    .settings-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 22px; }\n    .setting-full { grid-column: 1 / -1; }\n    .field-label { display: block; margin-bottom: 9px; color: var(--muted); font-size: .7rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }\n    .segment {\n      display: grid;\n      grid-auto-flow: column;\n      grid-auto-columns: 1fr;\n      gap: 4px;\n      padding: 4px;\n      background: #e9ede7;\n      border-radius: 12px;\n    }\n    .segment button {\n      min-height: 38px;\n      padding: 5px 8px;\n      border: 0;\n      border-radius: 9px;\n      color: var(--muted);\n      background: transparent;\n      cursor: pointer;\n      font-size: .76rem;\n      font-weight: 700;\n    }\n    .segment button.active { color: var(--ink); background: white; box-shadow: 0 2px 7px rgba(20, 35, 29, .08); }\n    .option-cards {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));\n      gap: 8px;\n    }\n    .option-card {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      min-height: 52px;\n      padding: 8px 12px;\n      border: 1px solid var(--line);\n      border-radius: 12px;\n      color: var(--muted);\n      background: white;\n      cursor: pointer;\n      font-size: .8rem;\n      font-weight: 700;\n      text-align: left;\n      transition: border-color .18s ease, background .18s ease, transform .18s ease;\n    }\n    .option-card:hover { transform: translateY(-1px); border-color: #bbc5bc; }\n    .option-card.active { color: var(--brand-dark); background: var(--brand-soft); border-color: color-mix(in srgb, var(--brand) 45%, white); }\n    .option-icon {\n      display: grid;\n      flex: none;\n      place-items: center;\n      width: 29px;\n      height: 29px;\n      border-radius: 9px;\n      background: var(--soft);\n      font-size: .95rem;\n    }\n    .option-card.active .option-icon { background: rgba(255, 255, 255, .72); }\n    .sub-setting { margin-top: 12px; padding: 13px; background: rgba(255,255,255,.62); border: 1px solid var(--line); border-radius: 13px; }\n    .sub-setting .option-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n    .sub-setting .option-icon { width: 42px; font-size: .78rem; letter-spacing: -.08em; white-space: nowrap; }\n    .check-row { display: flex; flex-wrap: wrap; gap: 9px; }\n    .check {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      min-height: 42px;\n      padding: 0 13px;\n      background: white;\n      border: 1px solid var(--line);\n      border-radius: 11px;\n      cursor: pointer;\n      font-size: .82rem;\n      font-weight: 600;\n    }\n    .check:has(input:checked) { color: var(--brand-dark); background: var(--brand-soft); border-color: #a7d4bf; }\n    input[type=\"checkbox\"] { width: 16px; height: 16px; accent-color: var(--brand); }\n    .empty {\n      display: grid;\n      place-items: center;\n      min-height: 420px;\n      padding: 48px 24px;\n      text-align: center;\n      background: rgba(255, 255, 255, .62);\n      border: 1px dashed #cfd5ce;\n      border-radius: 28px;\n    }\n    .empty-visual {\n      position: relative;\n      width: 112px;\n      height: 96px;\n      margin: 0 auto 28px;\n    }\n    .mini-card {\n      position: absolute;\n      inset: 8px 12px;\n      display: grid;\n      place-items: center;\n      background: white;\n      border: 1px solid var(--line);\n      border-radius: 16px;\n      box-shadow: 0 12px 28px rgba(24, 42, 34, .09);\n      font-size: 1.7rem;\n      font-weight: 700;\n    }\n    .mini-card:first-child { transform: rotate(-8deg) translate(-10px, 3px); color: var(--brand); }\n    .mini-card:last-child { transform: rotate(6deg) translate(11px, -3px); color: var(--coral); }\n    .empty h2 { margin-bottom: 10px; font-size: 1.5rem; }\n    .empty p { max-width: 430px; margin-bottom: 24px; color: var(--muted); line-height: 1.8; }\n\n    .editor-main { width: min(900px, 100%); margin: 0 auto; padding: 38px 20px 90px; }\n    .editor-head { margin-bottom: 30px; }\n    .editor-head h1 { margin-bottom: 8px; font-size: clamp(1.8rem, 4vw, 2.6rem); letter-spacing: -.045em; }\n    .editor-head p { color: var(--muted); }\n    .stack { display: grid; gap: 20px; }\n    .panel { padding: clamp(20px, 4vw, 28px); background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: 0 5px 20px rgba(28, 42, 36, .035); }\n    .panel-title { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-bottom: 17px; }\n    .panel-title h2 { margin: 0; font-size: 1.03rem; }\n    .input, .textarea {\n      width: 100%;\n      border: 1px solid #ccd3cb;\n      border-radius: 13px;\n      color: var(--ink);\n      background: #fbfcf9;\n      transition: border-color .18s ease, box-shadow .18s ease;\n    }\n    .input { min-height: 50px; padding: 0 15px; }\n    .textarea { min-height: 120px; padding: 14px 15px; resize: vertical; line-height: 1.7; }\n    .input:focus, .textarea:focus { outline: 0; border-color: var(--brand); box-shadow: 0 0 0 4px rgba(28, 107, 80, .1); background: white; }\n    .hint { margin: 8px 0 0; color: var(--muted); font-size: .78rem; line-height: 1.6; }\n    .import-panel { background: #1b2924; border-color: #1b2924; color: white; }\n    .import-panel .field-label, .import-panel .hint { color: #aebcb6; }\n    .import-panel .textarea { color: white; background: #111b17; border-color: #364640; }\n    .import-panel .btn-secondary { color: var(--ink); background: white; border-color: white; }\n    .import-panel .btn-secondary:hover { color: var(--ink); background: #eef1eb; }\n    .cards { display: grid; gap: 11px; }\n    .card-row {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(100px, .48fr) minmax(190px, .7fr) auto;\n      gap: 10px;\n      align-items: center;\n      padding: 11px;\n      background: #f8f9f6;\n      border: 1px solid var(--line);\n      border-radius: 15px;\n    }\n    .status-choice {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 4px;\n      min-height: 50px;\n      padding: 4px;\n      background: #e9ede7;\n      border-radius: 13px;\n    }\n    .status-choice button {\n      min-width: 0;\n      padding: 0 7px;\n      border: 0;\n      border-radius: 9px;\n      color: var(--muted);\n      background: transparent;\n      cursor: pointer;\n      font-size: .7rem;\n      font-weight: 700;\n      white-space: nowrap;\n      transition: transform .14s ease, background .18s ease, border-color .18s ease;\n    }\n    .status-choice button:hover { background: rgba(255,255,255,.65); }\n    .status-choice button:active { transform: scale(.96); }\n    .status-choice .unlearned.active { color: #a44a3c; background: var(--coral-soft); box-shadow: 0 2px 7px rgba(164,74,60,.1); }\n    .status-choice .learned.active { color: var(--brand-dark); background: var(--brand-soft); box-shadow: 0 2px 7px rgba(28,107,80,.1); }\n    .remove {\n      width: 42px;\n      height: 42px;\n      border: 0;\n      border-radius: 11px;\n      color: #a44235;\n      background: transparent;\n      cursor: pointer;\n      font-size: 1.2rem;\n    }\n    .remove:hover { background: var(--coral-soft); }\n\n    .play-shell {\n      height: 100dvh;\n      overflow: hidden;\n      display: flex;\n      flex-direction: column;\n      color: #f5f6f1;\n      background:\n        radial-gradient(\n          circle at 50% 30%,\n          color-mix(in srgb, var(--brand) 42%, #24302c) 0,\n          color-mix(in srgb, var(--brand) 20%, #14201c) 48%,\n          color-mix(in srgb, var(--brand) 8%, #0d1512) 100%\n        );\n    }\n    .play-top {\n      display: grid;\n      grid-template-columns: 1fr auto 1fr;\n      align-items: center;\n      padding: max(16px, env(safe-area-inset-top)) clamp(18px, 4vw, 38px) 12px;\n    }\n    .round {\n      display: grid;\n      place-items: center;\n      width: 44px;\n      height: 44px;\n      border: 1px solid rgba(255,255,255,.12);\n      border-radius: 50%;\n      color: white;\n      background: rgba(255,255,255,.08);\n      cursor: pointer;\n      backdrop-filter: blur(10px);\n    }\n    .round:hover { background: rgba(255,255,255,.14); }\n    .play-count { color: #c7d0cc; font-size: .8rem; font-weight: 700; letter-spacing: .14em; }\n    .part-tag { justify-self: end; padding: 8px 12px; color: #c7d0cc; background: rgba(255,255,255,.07); border-radius: 99px; font-size: .72rem; font-weight: 700; }\n    .play-progress {\n      height: 4px;\n      margin: 0 clamp(22px, 5vw, 60px);\n      overflow: hidden;\n      background: rgba(255,255,255,.1);\n      border-radius: 99px;\n    }\n    .play-progress span {\n      display: block;\n      width: 0;\n      height: 100%;\n      background: color-mix(in srgb, var(--brand) 72%, white);\n      border-radius: inherit;\n      transition: width .35s ease;\n    }\n    .play-area { position: relative; flex: 1; display: grid; place-items: center; min-height: 0; padding: 12px clamp(10px, 2vw, 28px); }\n    .study-card {\n      position: relative;\n      width: min(1180px, 100%);\n      height: min(64vh, 650px);\n      perspective: 1600px;\n      cursor: grab;\n      user-select: none;\n      touch-action: pan-y;\n      transition: transform .3s cubic-bezier(.2,.8,.2,1), opacity .3s ease;\n    }\n    .study-card.moving { transition: none; }\n    .card-inner { position: relative; width: 100%; height: 100%; transform-style: preserve-3d; transition: transform .45s cubic-bezier(.2,.75,.25,1); }\n    .card-inner.flipped { transform: rotateX(180deg); }\n    .card-face {\n      position: absolute;\n      inset: 0;\n      display: grid;\n      place-items: center;\n      padding: clamp(24px, 5vw, 68px);\n      overflow: hidden;\n      border: 1px solid rgba(255,255,255,.42);\n      border-radius: clamp(24px, 4vw, 34px);\n      backface-visibility: hidden;\n      box-shadow: 0 32px 80px rgba(0,0,0,.28);\n    }\n    .card-front { color: var(--ink); background: #fffefa; }\n    .card-back { color: var(--brand-dark); background: color-mix(in srgb, var(--brand-soft) 82%, white); transform: rotateX(180deg); }\n    .completion-face {\n      display: flex;\n      flex-direction: column;\n      justify-content: center;\n      text-align: center;\n      background:\n        radial-gradient(circle at 50% 10%, color-mix(in srgb, var(--brand-soft) 80%, transparent), transparent 42%),\n        #fffefa;\n    }\n    .completion-badge {\n      display: grid;\n      place-items: center;\n      width: 78px;\n      height: 78px;\n      margin-bottom: 24px;\n      border-radius: 24px;\n      color: white;\n      background: var(--brand);\n      box-shadow: 0 16px 32px color-mix(in srgb, var(--brand) 28%, transparent);\n      font-size: 2.2rem;\n      animation: badge-in .55s cubic-bezier(.2, 1.5, .4, 1) both;\n    }\n    .completion-kicker { margin-bottom: 9px; color: var(--brand); font-size: .72rem; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; }\n    .completion-face h2 { margin-bottom: 10px; font-size: clamp(2rem, 6vw, 3.8rem); letter-spacing: -.05em; }\n    .completion-face p { margin-bottom: 26px; color: var(--muted); font-size: clamp(.9rem, 2vw, 1.05rem); }\n    .completion-actions { display: flex; justify-content: center; gap: 10px; }\n    .completion-controls { opacity: .28; pointer-events: none; }\n    .spark {\n      position: absolute;\n      width: 9px;\n      height: 9px;\n      border-radius: 3px;\n      background: var(--spark);\n      animation: sparkle 1.8s ease-in-out infinite alternate;\n    }\n    .spark.one { top: 18%; left: 17%; --spark: #e6b84c; transform: rotate(18deg); }\n    .spark.two { top: 25%; right: 16%; --spark: #d66c74; animation-delay: -.7s; }\n    .spark.three { bottom: 20%; left: 12%; --spark: #61a9c2; animation-delay: -.3s; }\n    .spark.four { right: 11%; bottom: 22%; --spark: #71af8f; transform: rotate(45deg); animation-delay: -1s; }\n    @keyframes badge-in { from { opacity: 0; transform: scale(.55) rotate(-12deg); } }\n    @keyframes sparkle { to { transform: translateY(-7px) rotate(50deg) scale(1.3); opacity: .55; } }\n    .play-text {\n      width: 100%;\n      text-align: center;\n      font-size: clamp(3rem, 9.5vw, 8rem);\n      font-weight: 700;\n      line-height: 1.16;\n      letter-spacing: -.045em;\n      overflow-wrap: anywhere;\n    }\n    .play-text.compact { font-size: clamp(2.35rem, 6.5vw, 5.6rem); }\n    .play-text.long { font-size: clamp(1.75rem, 4.4vw, 3.8rem); line-height: 1.28; }\n    .swipe-label {\n      position: absolute;\n      top: clamp(20px, 4vw, 34px);\n      z-index: 8;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      padding: 12px 16px;\n      border: 2px solid currentColor;\n      border-radius: 13px;\n      font-size: clamp(.9rem, 2vw, 1.15rem);\n      font-weight: 700;\n      opacity: 0;\n      background: rgba(255, 254, 250, .9);\n      box-shadow: 0 10px 28px rgba(14, 24, 20, .12);\n      backdrop-filter: blur(12px);\n      pointer-events: none;\n      transition: opacity .08s linear;\n    }\n    .swipe-label.left { left: clamp(20px, 4vw, 34px); color: #d85f51; transform: rotate(-5deg); }\n    .swipe-label.right { right: clamp(20px, 4vw, 34px); color: var(--brand); transform: rotate(5deg); }\n    .play-controls {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: clamp(9px, 2.2vw, 22px);\n      padding: 12px 16px max(22px, env(safe-area-inset-bottom));\n    }\n    .control {\n      display: grid;\n      place-items: center;\n      width: clamp(50px, 10vw, 66px);\n      height: clamp(50px, 10vw, 66px);\n      border: 1px solid rgba(255,255,255,.13);\n      border-radius: 50%;\n      color: white;\n      background: rgba(255,255,255,.08);\n      cursor: pointer;\n      font-size: 1.25rem;\n      backdrop-filter: blur(10px);\n      transition: transform .18s ease, background .18s ease;\n    }\n    .control:hover { transform: translateY(-2px); background: rgba(255,255,255,.14); }\n    .control.large { width: clamp(58px, 12vw, 78px); height: clamp(58px, 12vw, 78px); }\n    .control.miss { color: #ff9d8f; }\n    .control.sound { color: color-mix(in srgb, var(--brand) 45%, white); background: color-mix(in srgb, var(--brand) 22%, transparent); }\n    .control.know { color: color-mix(in srgb, var(--brand) 55%, white); }\n\n    .toast {\n      position: fixed;\n      left: 50%;\n      bottom: 24px;\n      z-index: 50;\n      padding: 12px 17px;\n      border-radius: 12px;\n      color: white;\n      background: #16231e;\n      box-shadow: 0 12px 36px rgba(0,0,0,.2);\n      font-size: .82rem;\n      transform: translateX(-50%);\n      animation: toast .2s ease both;\n    }\n    @keyframes toast { from { opacity: 0; transform: translate(-50%, 8px); } }\n\n    .manual-dialog {\n      width: min(680px, calc(100% - 32px));\n      max-height: min(760px, calc(100dvh - 32px));\n      padding: 0;\n      overflow: auto;\n      color: var(--ink);\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: 24px;\n      box-shadow: 0 28px 90px rgba(17, 29, 24, .28);\n    }\n    .manual-dialog::backdrop { background: rgba(18, 28, 24, .48); backdrop-filter: blur(4px); }\n    .manual-head {\n      position: sticky;\n      top: 0;\n      z-index: 1;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n      padding: 22px 24px;\n      background: rgba(255, 255, 255, .94);\n      border-bottom: 1px solid var(--line);\n      backdrop-filter: blur(12px);\n    }\n    .manual-head h2 { margin: 0; font-size: 1.35rem; }\n    .manual-close { width: 40px; height: 40px; padding: 0; }\n    .manual-body { padding: 24px; }\n    .manual-intro { margin-bottom: 22px; color: var(--muted); line-height: 1.8; }\n    .manual-steps { display: grid; gap: 12px; margin: 0; padding: 0; list-style: none; counter-reset: manual; }\n    .manual-steps li {\n      position: relative;\n      min-height: 74px;\n      padding: 15px 16px 15px 64px;\n      background: #f7f9f5;\n      border: 1px solid var(--line);\n      border-radius: 15px;\n      line-height: 1.65;\n      counter-increment: manual;\n    }\n    .manual-steps li::before {\n      content: counter(manual);\n      position: absolute;\n      top: 15px;\n      left: 16px;\n      display: grid;\n      place-items: center;\n      width: 32px;\n      height: 32px;\n      color: white;\n      background: var(--brand);\n      border-radius: 10px;\n      font-weight: 700;\n    }\n    .manual-steps strong { display: block; margin-bottom: 2px; }\n    .manual-tip { margin: 18px 0 0; padding: 14px 16px; color: var(--brand-dark); background: var(--brand-soft); border-radius: 13px; line-height: 1.7; }\n\n    @media (max-width: 700px) {\n      .topbar { min-height: 68px; padding-inline: 18px; }\n      .brand-sub { display: none; }\n      .header-actions { gap: 8px; }\n      .help-button { width: 40px; min-height: 40px; }\n      .theme-picker summary, .data-menu summary { width: 40px; height: 40px; }\n      .theme-options { gap: 7px; padding: 10px; }\n      .theme-dot { width: 17px; height: 17px; border-width: 2px; }\n      .header-actions .btn-primary { width: 44px; padding: 0; font-size: 0; }\n      .header-actions .btn-primary .icon { font-size: 1.2rem; }\n      .hero { align-items: start; flex-direction: column; margin-bottom: 26px; }\n      .hero .btn { width: 100%; }\n      .deck-main { grid-template-columns: 1fr; gap: 18px; padding: 21px; }\n      .deck-summary { grid-template-columns: 58px minmax(0, 1fr); gap: 13px; }\n      .deck-icon { width: 56px; height: 50px; }\n      .deck-actions .btn { flex: 1; }\n      .deck-setup { padding: 0 14px 14px; }\n      .setup-panel { padding: 18px; }\n      .settings-grid { grid-template-columns: 1fr; gap: 18px; }\n      .setting-full { grid-column: auto; }\n      .card-row { grid-template-columns: 1fr 1fr 42px; }\n      .card-row .part-input { grid-column: 1; }\n      .card-row .status-choice { grid-column: 2; }\n      .card-row .remove { grid-column: 3; grid-row: 1 / 3; }\n      .play-top { grid-template-columns: 1fr auto 1fr; }\n      .study-card { height: min(58vh, 540px); }\n      .completion-actions { width: 100%; flex-direction: column; }\n      .completion-actions .btn { width: 100%; }\n    }\n    @media (prefers-reduced-motion: reduce) {\n      *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; transition-duration: .01ms !important; }\n    }\n  </style>\n</head>\n<body>\n  <div id=\"app\"></div>\n  <script>\n    const STORAGE_KEY = \"edu_flashcards_data\";\n    const THEME_KEY = \"edu_flashcards_theme\";\n    const AUTO_PLAY_WAIT_MS = 2500;\n    const SAMPLE_DECK = {\n      id: \"sample-jhs3-english\",\n      name: \"中学3年 英単語サンプル\",\n      cards: [\n        [\"environment\", \"環境\", \"Part 1\"],\n        [\"experience\", \"経験\", \"Part 1\"],\n        [\"important\", \"重要な\", \"Part 1\"],\n        [\"international\", \"国際的な\", \"Part 1\"],\n        [\"communicate\", \"意思を伝える\", \"Part 1\"],\n        [\"continue\", \"続ける\", \"Part 1\"],\n        [\"improve\", \"改善する・上達する\", \"Part 1\"],\n        [\"opportunity\", \"機会\", \"Part 2\"],\n        [\"necessary\", \"必要な\", \"Part 2\"],\n        [\"especially\", \"特に\", \"Part 2\"],\n        [\"understand\", \"理解する\", \"Part 2\"],\n        [\"remember\", \"覚えている\", \"Part 2\"],\n        [\"choose\", \"選ぶ\", \"Part 2\"],\n        [\"protect\", \"守る\", \"Part 2\"],\n        [\"future\", \"未来\", \"Part 3\"],\n        [\"culture\", \"文化\", \"Part 3\"],\n        [\"peace\", \"平和\", \"Part 3\"],\n        [\"relationship\", \"関係\", \"Part 3\"],\n        [\"solve\", \"解決する\", \"Part 3\"],\n        [\"believe\", \"信じる\", \"Part 3\"]\n      ].map(([en, ja, part], index) => ({\n        id: `sample-card-${index + 1}`,\n        en,\n        ja,\n        part,\n        status: \"unlearned\"\n      }))\n    };\n\n    const state = {\n      view: \"list\",\n      decks: [],\n      editingDeck: null,\n      expandedDeckId: null,\n      playConfig: {\n        deckId: null,\n        targetStatus: \"all\",\n        selectedParts: [],\n        frontSide: \"en\",\n        shuffle: false,\n        autoPlayAudio: true,\n        displayMode: \"normal\",\n        typewriterSpeed: 150,\n        autoPlayMode: \"manual\"\n      },\n      playState: {\n        cards: [],\n        currentIndex: 0,\n        isFlipped: false,\n        completed: false,\n        typingInterval: null,\n        autoPlayTimeout: null\n      }\n    };\n\n    const app = document.getElementById(\"app\");\n    const uid = () => Math.random().toString(36).slice(2, 10);\n    const escapeHtml = value => String(value ?? \"\")\n      .replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\")\n      .replace(/\"/g, \"&quot;\").replace(/'/g, \"&#039;\");\n\n    function loadData() {\n      const saved = localStorage.getItem(STORAGE_KEY);\n      if (saved === null) {\n        state.decks = [JSON.parse(JSON.stringify(SAMPLE_DECK))];\n        saveData();\n        return;\n      }\n      try { state.decks = JSON.parse(saved) || []; }\n      catch { state.decks = []; }\n    }\n    function saveData() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state.decks)); }\n    function toast(message) {\n      document.querySelector(\".toast\")?.remove();\n      const el = document.createElement(\"div\");\n      el.className = \"toast\";\n      el.textContent = message;\n      document.body.append(el);\n      setTimeout(() => el.remove(), 2200);\n    }\n    function brand() {\n      return `<div class=\"brand\"><span class=\"brand-mark\">F</span><div><div class=\"brand-name\">Flashcards</div><div class=\"brand-sub\">English learning</div></div></div>`;\n    }\n    function themePicker() {\n      const themes = [\n        [\"forest\", \"#1c6b50\", \"フォレスト\"],\n        [\"ocean\", \"#376b8c\", \"オーシャン\"],\n        [\"indigo\", \"#5b5f97\", \"インディゴ\"],\n        [\"plum\", \"#855d78\", \"プラム\"],\n        [\"clay\", \"#a05f49\", \"クレイ\"],\n        [\"mustard\", \"#927126\", \"マスタード\"]\n      ];\n      const current = document.documentElement.dataset.theme || \"forest\";\n      return `<details class=\"theme-picker\">\n        <summary aria-label=\"テーマカラーを選ぶ\" title=\"テーマカラー\">🎨</summary>\n        <div class=\"theme-options\" aria-label=\"テーマカラー\">${themes.map(([id, color, label]) =>\n          `<button class=\"theme-dot ${current === id ? \"active\" : \"\"}\" style=\"--dot:${color}\" aria-label=\"${label}\" title=\"${label}\" onclick=\"setTheme('${id}')\"></button>`).join(\"\")}</div>\n      </details>`;\n    }\n    function setTheme(theme) {\n      document.documentElement.dataset.theme = theme;\n      localStorage.setItem(THEME_KEY, theme);\n      render();\n    }\n    function dataMenu() {\n      return `<details class=\"data-menu\">\n        <summary aria-label=\"単語帳データの管理\" title=\"バックアップ\">⇅</summary>\n        <div class=\"data-options\">\n          <button onclick=\"exportData()\"><span class=\"icon\">↓</span> ファイルに書き出す</button>\n          <button onclick=\"document.getElementById('importFile').click()\"><span class=\"icon\">↑</span> ファイルから読み込む</button>\n        </div>\n        <input id=\"importFile\" type=\"file\" accept=\".json,application/json\" hidden onchange=\"importData(this)\">\n      </details>`;\n    }\n    function manualDialog() {\n      return `<dialog class=\"manual-dialog\" id=\"manualDialog\" onclick=\"closeManualFromBackdrop(event)\">\n        <div class=\"manual-head\">\n          <h2>Flashcards の使い方</h2>\n          <button class=\"btn btn-ghost manual-close\" aria-label=\"使い方を閉じる\" onclick=\"closeManual()\">×</button>\n        </div>\n        <div class=\"manual-body\">\n          <p class=\"manual-intro\">単語を登録して、学習方法を選ぶだけで始められます。まずはサンプル単語帳で操作を試してみてください。</p>\n          <ol class=\"manual-steps\">\n            <li><strong>単語帳を用意する</strong>「新しい単語帳」から1枚ずつ追加するか、Excelの「英語・日本語・パート」の3列をコピーしてまとめて貼り付けます。</li>\n            <li><strong>学習方法を選ぶ</strong>一覧の「学習する」を押し、未習得だけ・Part別・シャッフル・自動再生などを選びます。</li>\n            <li><strong>カードで覚える</strong>カードを押して裏返します。左右のボタンやスワイプで「未習得」「習得済み」を記録できます。</li>\n            <li><strong>データを保管する</strong>上部の「⇅」からファイルへ書き出せます。別の端末では、そのファイルを読み込んで続けられます。</li>\n          </ol>\n          <p class=\"manual-tip\">🎨 パレットから好きなテーマカラーも選べます。単語帳と学習状況は、この端末のブラウザに自動保存されます。</p>\n        </div>\n      </dialog>`;\n    }\n    function openManual() { document.getElementById(\"manualDialog\")?.showModal(); }\n    function closeManual() { document.getElementById(\"manualDialog\")?.close(); }\n    function closeManualFromBackdrop(event) { if (event.target.id === \"manualDialog\") closeManual(); }\n    function exportData() {\n      const backup = {\n        app: \"Flashcards\",\n        version: 1,\n        exportedAt: new Date().toISOString(),\n        decks: state.decks\n      };\n      const blob = new Blob([JSON.stringify(backup, null, 2)], { type: \"application/json\" });\n      const url = URL.createObjectURL(blob);\n      const link = document.createElement(\"a\");\n      const date = new Date().toISOString().slice(0, 10);\n      link.href = url;\n      link.download = `flashcards-backup-${date}.json`;\n      document.body.append(link);\n      link.click();\n      link.remove();\n      setTimeout(() => URL.revokeObjectURL(url), 1000);\n      toast(`${state.decks.length}個の単語帳を書き出しました`);\n    }\n    function importData(input) {\n      const file = input.files?.[0];\n      if (!file) return;\n      const reader = new FileReader();\n      reader.onload = () => {\n        try {\n          const parsed = JSON.parse(reader.result);\n          const source = Array.isArray(parsed) ? parsed : parsed.decks;\n          if (!Array.isArray(source)) throw new Error(\"invalid\");\n          const imported = source.map(deck => ({\n            id: typeof deck.id === \"string\" ? deck.id : `deck-${uid()}`,\n            name: typeof deck.name === \"string\" && deck.name.trim() ? deck.name : \"読み込んだ単語帳\",\n            cards: Array.isArray(deck.cards) ? deck.cards.map(card => ({\n              id: typeof card.id === \"string\" ? card.id : `c-${uid()}`,\n              en: typeof card.en === \"string\" ? card.en : \"\",\n              ja: typeof card.ja === \"string\" ? card.ja : \"\",\n              part: typeof card.part === \"string\" ? card.part : \"\",\n              status: card.status === \"learned\" ? \"learned\" : \"unlearned\"\n            })) : []\n          }));\n          if (!confirm(`${imported.length}個の単語帳を読み込みます。現在のデータは残り、同じ単語帳は更新されます。`)) return;\n          const merged = new Map(state.decks.map(deck => [deck.id, deck]));\n          imported.forEach(deck => merged.set(deck.id, deck));\n          state.decks = [...merged.values()];\n          saveData();\n          state.expandedDeckId = null;\n          render();\n          toast(`${imported.length}個の単語帳を読み込みました`);\n        } catch {\n          toast(\"このファイルは読み込めませんでした\");\n        } finally {\n          input.value = \"\";\n        }\n      };\n      reader.onerror = () => {\n        input.value = \"\";\n        toast(\"ファイルを読み込めませんでした\");\n      };\n      reader.readAsText(file);\n    }\n    function render() {\n      clearAutoPlayTimer();\n      app.innerHTML = state.view === \"list\" ? renderList() : state.view === \"edit\" ? renderEdit() : renderPlay();\n      if (state.view === \"edit\") renderEditCards();\n      if (state.view === \"play\") {\n        updatePlayCard(true);\n        setupSwipeEvents();\n      }\n    }\n\n    function renderList() {\n      const welcome = `<div class=\"empty\">\n          <div>\n            <div class=\"empty-visual\"><div class=\"mini-card\">A</div><div class=\"mini-card\">あ</div></div>\n            <h2>最初の単語帳をつくりましょう</h2>\n            <p>英語と日本語を登録するだけ。Excelからまとめて貼り付けることもできます。</p>\n            <button class=\"btn btn-primary\" onclick=\"createNewDeck()\"><span class=\"icon\">＋</span> 単語帳をつくる</button>\n          </div>\n        </div>`;\n      const deckSection = state.decks.length ? `<section class=\"deck-section\" aria-labelledby=\"deckSectionTitle\">\n        <div class=\"deck-section-head\">\n          <h2 id=\"deckSectionTitle\">${state.decks.length === 1 && state.decks[0].id === SAMPLE_DECK.id ? \"お試し用のサンプル\" : \"単語帳\"}</h2>\n          <p>${state.decks.length}冊</p>\n        </div>\n        <div class=\"deck-list\">${state.decks.map(renderDeck).join(\"\")}</div>\n      </section>` : \"\";\n      return `<div class=\"shell\">\n        <header class=\"topbar\">${brand()}<div class=\"header-actions\"><button class=\"btn help-button\" aria-label=\"使い方を開く\" title=\"使い方\" onclick=\"openManual()\">?</button>${dataMenu()}${themePicker()}<button class=\"btn btn-primary\" onclick=\"createNewDeck()\"><span class=\"icon\">＋</span> 新しい単語帳</button></div></header>\n        <main class=\"main\">\n          ${welcome}\n          ${deckSection}\n        </main>\n        ${manualDialog()}\n      </div>`;\n    }\n\n    function renderDeck(deck) {\n      const total = deck.cards.length;\n      const learned = deck.cards.filter(card => card.status === \"learned\").length;\n      const percent = total ? Math.round(learned / total * 100) : 0;\n      const expanded = state.expandedDeckId === deck.id;\n      const parts = [...new Set(deck.cards.map(card => card.part).filter(Boolean))].sort();\n      return `<article class=\"deck\">\n        <div class=\"deck-main\">\n          <div class=\"deck-summary\" onclick=\"toggleSetup('${deck.id}')\">\n            <div class=\"deck-icon\" aria-hidden=\"true\"><span class=\"deck-icon-card\"></span><span class=\"deck-icon-card\">A</span></div>\n            <div class=\"deck-summary-body\">\n              <div class=\"deck-title-row\"><h2>${escapeHtml(deck.name)}</h2><span class=\"count-pill\">${total} cards</span></div>\n              <div class=\"deck-meta\"><span>${learned} 語をマスター</span><span>${percent}%</span></div>\n              <div class=\"progress\" aria-label=\"学習進捗 ${percent}%\"><span style=\"width:${percent}%\"></span></div>\n            </div>\n          </div>\n          <div class=\"deck-actions\">\n            <button class=\"btn btn-secondary\" onclick=\"event.stopPropagation(); editDeck('${deck.id}')\">編集</button>\n            <button class=\"btn ${expanded ? \"btn-secondary\" : \"btn-primary\"}\" onclick=\"event.stopPropagation(); toggleSetup('${deck.id}')\">${expanded ? \"設定を閉じる\" : \"学習する\"}</button>\n          </div>\n        </div>\n        ${expanded ? renderSetup(deck, parts) : \"\"}\n      </article>`;\n    }\n\n    function segment(options, current, handler) {\n      return `<div class=\"segment\">${options.map(([value, label]) =>\n        `<button class=\"${current === value ? \"active\" : \"\"}\" onclick=\"${handler}('${value}')\">${label}</button>`).join(\"\")}</div>`;\n    }\n\n    function choiceCards(options, current, handler) {\n      return `<div class=\"option-cards\">${options.map(([value, icon, label]) =>\n        `<button class=\"option-card ${current === value ? \"active\" : \"\"}\" aria-pressed=\"${current === value}\" onclick=\"${handler}('${value}')\"><span class=\"option-icon\">${icon}</span><span>${label}</span></button>`).join(\"\")}</div>`;\n    }\n\n    function renderSetup(deck, parts) {\n      const c = state.playConfig;\n      const playKind = c.autoPlayMode === \"manual\" ? \"manual\" : \"auto\";\n      return `<div class=\"deck-setup\"><div class=\"setup-panel\">\n        <div class=\"settings-grid\">\n          <div><span class=\"field-label\">学習するカード</span>${choiceCards([[\"all\",\"◎\",\"すべて\"],[\"unlearned\",\"△\",\"未習得\"],[\"learned\",\"✓\",\"習得済み\"]], c.targetStatus, \"setTarget\")}</div>\n          <div>\n            <span class=\"field-label\">進め方</span>\n            ${choiceCards([[\"manual\",\"☝\",\"手動で進める\"],[\"auto\",\"▶\",\"オート再生\"]], playKind, \"setPlayKind\")}\n            ${playKind === \"auto\" ? `<div class=\"sub-setting\"><span class=\"field-label\">再生する順番</span>${choiceCards([[\"en_only\",\"A\",\"英語のみ\"],[\"ja_only\",\"あ\",\"日本語のみ\"],[\"en_ja\",\"A→あ\",\"英語→日本語\"],[\"ja_en\",\"あ→A\",\"日本語→英語\"]], c.autoPlayMode, \"setAutoPlayMode\")}</div>` : \"\"}\n          </div>\n          <div>\n            <span class=\"field-label\">表示</span>\n            ${choiceCards([[\"normal\",\"▣\",\"一度に表示\"],[\"typewriter\",\"⌨\",\"1文字ずつ\"]], c.displayMode, \"setDisplayMode\")}\n            ${c.displayMode === \"typewriter\" ? `<div style=\"margin-top:10px\"><span class=\"field-label\">文字のスピード</span>${segment([[\"250\",\"ゆっくり\"],[\"150\",\"ふつう\"],[\"70\",\"速い\"]], String(c.typewriterSpeed), \"setTypewriterSpeed\")}</div>` : \"\"}\n          </div>\n          ${c.autoPlayMode === \"manual\" ? `<div><span class=\"field-label\">最初に表示する面</span>${choiceCards([[\"en\",\"A\",\"英語\"],[\"ja\",\"あ\",\"日本語\"]], c.frontSide, \"setFrontSide\")}</div>` : \"\"}\n          <div class=\"${parts.length ? \"\" : \"setting-full\"}\"><span class=\"field-label\">オプション</span><div class=\"check-row\">\n            <label class=\"check\"><span class=\"option-icon\">🔊</span><input type=\"checkbox\" ${c.autoPlayAudio ? \"checked\" : \"\"} onchange=\"setOption('autoPlayAudio', this.checked)\"> 自動で発音</label>\n            <label class=\"check\"><span class=\"option-icon\">⇄</span><input type=\"checkbox\" ${c.shuffle ? \"checked\" : \"\"} onchange=\"setOption('shuffle', this.checked)\"> シャッフル</label>\n          </div></div>\n          ${parts.length ? `<div><span class=\"field-label\">パート</span><div class=\"check-row\">${parts.map(part =>\n            `<label class=\"check\"><input type=\"checkbox\" ${c.selectedParts.includes(part) ? \"checked\" : \"\"} onchange=\"togglePartSelection('${escapeHtml(part)}')\"> ${escapeHtml(part)}</label>`).join(\"\")}</div></div>` : \"\"}\n          <div class=\"setting-full\"><button class=\"btn btn-primary btn-wide\" onclick=\"startPlay('${deck.id}')\">学習をスタート <span class=\"icon\">→</span></button></div>\n        </div>\n      </div></div>`;\n    }\n\n    function setTarget(value) { state.playConfig.targetStatus = value; render(); }\n    function setDisplayMode(value) { state.playConfig.displayMode = value; render(); }\n    function setTypewriterSpeed(value) { state.playConfig.typewriterSpeed = Number(value); render(); }\n    function setFrontSide(value) { state.playConfig.frontSide = value; render(); }\n    function setOption(key, value) { state.playConfig[key] = value; render(); }\n    function setPlayKind(kind) {\n      if (kind === \"manual\") state.playConfig.autoPlayMode = \"manual\";\n      else if (state.playConfig.autoPlayMode === \"manual\") {\n        state.playConfig.autoPlayMode = \"en_ja\";\n        state.playConfig.frontSide = \"en\";\n      }\n      render();\n    }\n    function setAutoPlayMode(mode) {\n      state.playConfig.autoPlayMode = mode;\n      if ([\"en_only\",\"en_ja\"].includes(mode)) state.playConfig.frontSide = \"en\";\n      if ([\"ja_only\",\"ja_en\"].includes(mode)) state.playConfig.frontSide = \"ja\";\n      render();\n    }\n    function togglePartSelection(part) {\n      const selected = state.playConfig.selectedParts;\n      const index = selected.indexOf(part);\n      index >= 0 ? selected.splice(index, 1) : selected.push(part);\n      render();\n    }\n    function toggleSetup(id) {\n      state.expandedDeckId = state.expandedDeckId === id ? null : id;\n      if (state.expandedDeckId) {\n        const deck = state.decks.find(item => item.id === id);\n        state.playConfig.selectedParts = [...new Set(deck.cards.map(card => card.part).filter(Boolean))];\n      }\n      render();\n    }\n\n    function createNewDeck() {\n      state.editingDeck = { id: \"deck-\" + uid(), name: \"新しい単語帳\", cards: [] };\n      state.view = \"edit\";\n      render();\n    }\n    function editDeck(id) {\n      const deck = state.decks.find(item => item.id === id);\n      if (!deck) return;\n      state.editingDeck = JSON.parse(JSON.stringify(deck));\n      state.view = \"edit\";\n      render();\n    }\n    function renderEdit() {\n      const importPanel = `<section class=\"panel import-panel\" id=\"importPanel\">\n        <div class=\"panel-title\"><h2>Excelからまとめて追加</h2></div>\n        <label class=\"field-label\" for=\"importArea\">英語・日本語・パートの順に貼り付け</label>\n        <textarea class=\"textarea\" id=\"importArea\" placeholder=\"apple&#9;りんご&#9;Part 1&#10;banana&#9;バナナ&#9;Part 1\"></textarea>\n        <p class=\"hint\">Excelの3列をコピーして、そのまま貼り付けられます。</p>\n        <button class=\"btn btn-secondary btn-wide\" style=\"margin-top:16px\" onclick=\"importCards()\">カードに追加</button>\n      </section>`;\n      const cardsPanel = `<section class=\"panel\" id=\"cardsPanel\">\n        <div class=\"panel-title\"><h2>カード <span id=\"cardCount\" class=\"count-pill\"></span></h2><button class=\"btn btn-secondary\" onclick=\"addEmptyCard()\">＋ 1枚追加</button></div>\n        <div id=\"editCards\" class=\"cards\"></div>\n      </section>`;\n      const cardTools = state.editingDeck.cards.length ? `${cardsPanel}${importPanel}` : `${importPanel}${cardsPanel}`;\n      return `<div class=\"shell\">\n        <header class=\"topbar\">\n          <button class=\"btn btn-ghost\" onclick=\"cancelEdit()\">← 戻る</button>\n          ${brand()}\n          <button class=\"btn btn-primary\" onclick=\"saveEdit()\">保存</button>\n        </header>\n        <main class=\"editor-main\">\n          <div class=\"editor-head\"><p class=\"eyebrow\">Deck editor</p><h1>単語帳を編集</h1><p>授業や単元ごとに、カードを整理できます。</p></div>\n          <div class=\"stack\">\n            <section class=\"panel\"><label class=\"field-label\" for=\"deckName\">単語帳の名前</label><input class=\"input\" id=\"deckName\" value=\"${escapeHtml(state.editingDeck.name)}\" placeholder=\"例：Part 3 — Travel\"></section>\n            ${cardTools}\n            <button class=\"btn btn-danger btn-wide\" onclick=\"deleteDeck()\">この単語帳を削除</button>\n          </div>\n        </main>\n      </div>`;\n    }\n    function renderEditCards() {\n      const cards = state.editingDeck.cards;\n      document.getElementById(\"cardCount\").textContent = `${cards.length}枚`;\n      document.getElementById(\"editCards\").innerHTML = cards.length ? cards.map((card, index) => `\n        <div class=\"card-row\">\n          <input class=\"input\" value=\"${escapeHtml(card.en)}\" placeholder=\"English\" oninput=\"updateCard(${index}, 'en', this.value)\">\n          <input class=\"input\" value=\"${escapeHtml(card.ja)}\" placeholder=\"日本語\" oninput=\"updateCard(${index}, 'ja', this.value)\">\n          <input class=\"input part-input\" value=\"${escapeHtml(card.part)}\" placeholder=\"Part\" oninput=\"updateCard(${index}, 'part', this.value)\">\n          <div class=\"status-choice\" role=\"group\" aria-label=\"${escapeHtml(card.en || card.ja || `カード${index + 1}`)}の学習状態\">\n            <button class=\"unlearned ${card.status !== \"learned\" ? \"active\" : \"\"}\" aria-pressed=\"${card.status !== \"learned\"}\" onclick=\"setCardStatus(${index}, 'unlearned', this.parentElement)\">△ 未習得</button>\n            <button class=\"learned ${card.status === \"learned\" ? \"active\" : \"\"}\" aria-pressed=\"${card.status === \"learned\"}\" onclick=\"setCardStatus(${index}, 'learned', this.parentElement)\">✓ 習得済み</button>\n          </div>\n          <button class=\"remove\" aria-label=\"カードを削除\" onclick=\"removeCard(${index})\">×</button>\n        </div>`).join(\"\") : `<div class=\"empty\" style=\"min-height:190px\"><div><h2>カードはまだありません</h2><p>1枚ずつ追加するか、Excelからまとめて貼り付けてください。</p></div></div>`;\n    }\n    function updateCard(index, key, value) { state.editingDeck.cards[index][key] = value; }\n    function setCardStatus(index, status, group) {\n      state.editingDeck.cards[index].status = status;\n      group.querySelectorAll(\"button\").forEach(button => {\n        const active = button.classList.contains(status);\n        button.classList.toggle(\"active\", active);\n        button.setAttribute(\"aria-pressed\", String(active));\n      });\n    }\n    function addEmptyCard() {\n      state.editingDeck.cards.push({ id: \"c-\" + uid(), en: \"\", ja: \"\", part: \"\", status: \"unlearned\" });\n      renderEditCards();\n      positionImportPanel();\n      document.querySelector(\".card-row:last-child input\")?.focus();\n    }\n    function removeCard(index) {\n      state.editingDeck.cards.splice(index, 1);\n      renderEditCards();\n      positionImportPanel();\n    }\n    function positionImportPanel() {\n      const stack = document.querySelector(\".editor-main .stack\");\n      const importPanel = document.getElementById(\"importPanel\");\n      const cardsPanel = document.getElementById(\"cardsPanel\");\n      if (!stack || !importPanel || !cardsPanel) return;\n      if (state.editingDeck.cards.length) cardsPanel.after(importPanel);\n      else importPanel.after(cardsPanel);\n    }\n    function importCards() {\n      const area = document.getElementById(\"importArea\");\n      let count = 0;\n      area.value.split(/\\r?\\n/).forEach(line => {\n        const [en = \"\", ja = \"\", part = \"\"] = line.split(\"\\t\").map(value => value.trim());\n        if (en || ja) {\n          state.editingDeck.cards.push({ id: \"c-\" + uid(), en, ja, part, status: \"unlearned\" });\n          count++;\n        }\n      });\n      if (!count) return toast(\"追加できるデータが見つかりませんでした\");\n      area.value = \"\";\n      renderEditCards();\n      positionImportPanel();\n      toast(`${count}枚のカードを追加しました`);\n    }\n    function cancelEdit() { state.editingDeck = null; state.view = \"list\"; render(); }\n    function saveEdit() {\n      state.editingDeck.name = document.getElementById(\"deckName\").value.trim() || \"名称未設定の単語帳\";\n      state.editingDeck.cards = state.editingDeck.cards.filter(card => card.en.trim() || card.ja.trim());\n      const index = state.decks.findIndex(deck => deck.id === state.editingDeck.id);\n      index >= 0 ? state.decks[index] = state.editingDeck : state.decks.push(state.editingDeck);\n      saveData();\n      state.editingDeck = null;\n      state.view = \"list\";\n      render();\n      toast(\"単語帳を保存しました\");\n    }\n    function deleteDeck() {\n      const exists = state.decks.some(deck => deck.id === state.editingDeck.id);\n      if (!exists) return cancelEdit();\n      if (!confirm(\"この単語帳を削除しますか？\")) return;\n      state.decks = state.decks.filter(deck => deck.id !== state.editingDeck.id);\n      saveData();\n      cancelEdit();\n    }\n\n    function startPlay(deckId) {\n      const deck = state.decks.find(item => item.id === deckId);\n      let cards = [...deck.cards];\n      if (state.playConfig.targetStatus !== \"all\") cards = cards.filter(card => card.status === state.playConfig.targetStatus);\n      if (state.playConfig.selectedParts.length) cards = cards.filter(card => !card.part || state.playConfig.selectedParts.includes(card.part));\n      if (!cards.length) return toast(\"条件に合うカードがありません\");\n      if (state.playConfig.shuffle) {\n        for (let i = cards.length - 1; i > 0; i--) {\n          const j = Math.floor(Math.random() * (i + 1));\n          [cards[i], cards[j]] = [cards[j], cards[i]];\n        }\n      }\n      state.playConfig.deckId = deckId;\n      state.playState.cards = cards;\n      state.playState.currentIndex = 0;\n      state.playState.isFlipped = false;\n      state.playState.completed = false;\n      state.view = \"play\";\n      render();\n    }\n    function renderPlay() {\n      return `<div class=\"play-shell\">\n        <header class=\"play-top\">\n          <button class=\"round\" aria-label=\"学習を終了\" onclick=\"endPlay()\">×</button>\n          <div class=\"play-count\" id=\"playCount\"></div>\n          <div class=\"part-tag\" id=\"playPart\"></div>\n        </header>\n        <div class=\"play-progress\" aria-label=\"学習の進捗\"><span id=\"playProgressBar\"></span></div>\n        <main class=\"play-area\">\n          <div class=\"study-card\" id=\"studyCard\" onclick=\"flipCard(event)\">\n            <div class=\"swipe-label left\" id=\"missLabel\"><span>×</span> 分からない</div>\n            <div class=\"swipe-label right\" id=\"knowLabel\"><span>✓</span> 習得済み</div>\n            <div class=\"card-inner\" id=\"cardInner\">\n              <section class=\"card-face card-front\"><div class=\"play-text\" id=\"frontText\"></div></section>\n              <section class=\"card-face card-back\"><div class=\"play-text\" id=\"backText\"></div></section>\n            </div>\n          </div>\n        </main>\n        <nav class=\"play-controls\" aria-label=\"学習操作\">\n          <button class=\"control\" aria-label=\"前のカード\" onclick=\"prevCard()\">←</button>\n          <button class=\"control large miss\" aria-label=\"もう一度\" onclick=\"markCard('unlearned')\">×</button>\n          <button class=\"control large sound\" aria-label=\"発音を聞く\" onclick=\"playAudio()\">◖))</button>\n          <button class=\"control large know\" aria-label=\"覚えた\" onclick=\"markCard('learned')\">✓</button>\n          <button class=\"control\" aria-label=\"次のカード\" onclick=\"nextCard()\">→</button>\n        </nav>\n      </div>`;\n    }\n    function clearAutoPlayTimer() {\n      if (state.playState.autoPlayTimeout) clearTimeout(state.playState.autoPlayTimeout);\n      state.playState.autoPlayTimeout = null;\n    }\n    function typeText(element, text, done) {\n      clearInterval(state.playState.typingInterval);\n      element.textContent = \"\";\n      let i = 0;\n      state.playState.typingInterval = setInterval(() => {\n        element.textContent += text.charAt(i++);\n        if (i >= text.length) { clearInterval(state.playState.typingInterval); state.playState.typingInterval = null; done?.(); }\n      }, state.playConfig.typewriterSpeed);\n    }\n    function handleAutoPlayNext() {\n      const mode = state.playConfig.autoPlayMode;\n      if (mode === \"manual\") return;\n      state.playState.autoPlayTimeout = setTimeout(() => {\n        if ([\"en_ja\",\"ja_en\"].includes(mode) && !state.playState.isFlipped) flipCard();\n        else nextCard();\n      }, AUTO_PLAY_WAIT_MS);\n    }\n    function updatePlayCard(forceFront = true) {\n      const card = state.playState.cards[state.playState.currentIndex];\n      if (!card) return;\n      const frontIsEnglish = state.playConfig.frontSide === \"en\";\n      const front = frontIsEnglish ? card.en : card.ja;\n      const back = frontIsEnglish ? card.ja : card.en;\n      const setTextSize = (element, text) => {\n        element.classList.toggle(\"compact\", text.length > 20 && text.length <= 40);\n        element.classList.toggle(\"long\", text.length > 40);\n      };\n      document.getElementById(\"playCount\").textContent = `${String(state.playState.currentIndex + 1).padStart(2,\"0\")} / ${String(state.playState.cards.length).padStart(2,\"0\")}`;\n      document.getElementById(\"playProgressBar\").style.width = `${(state.playState.currentIndex + 1) / state.playState.cards.length * 100}%`;\n      document.getElementById(\"playPart\").textContent = card.part || \"ALL\";\n      const frontText = document.getElementById(\"frontText\");\n      const backText = document.getElementById(\"backText\");\n      setTextSize(frontText, front);\n      setTextSize(backText, back);\n      backText.textContent = back;\n      if (forceFront) {\n        state.playState.isFlipped = false;\n        document.getElementById(\"cardInner\").classList.remove(\"flipped\");\n        const studyCard = document.getElementById(\"studyCard\");\n        studyCard.style.transform = \"\";\n        studyCard.style.opacity = \"1\";\n      }\n      const complete = () => {\n        if (state.playConfig.autoPlayAudio) playAudio();\n        handleAutoPlayNext();\n      };\n      if (state.playConfig.displayMode === \"typewriter\" && forceFront) typeText(frontText, front, complete);\n      else { frontText.textContent = front; complete(); }\n    }\n    function flipCard() {\n      if (state.playState.completed) return;\n      if (state.playState.typingInterval) {\n        clearInterval(state.playState.typingInterval);\n        state.playState.typingInterval = null;\n        const card = state.playState.cards[state.playState.currentIndex];\n        document.getElementById(\"frontText\").textContent = state.playConfig.frontSide === \"en\" ? card.en : card.ja;\n        return handleAutoPlayNext();\n      }\n      state.playState.isFlipped = !state.playState.isFlipped;\n      document.getElementById(\"cardInner\").classList.toggle(\"flipped\", state.playState.isFlipped);\n      clearAutoPlayTimer();\n      if (state.playConfig.autoPlayAudio) setTimeout(playAudio, 180);\n      handleAutoPlayNext();\n    }\n    function nextCard() {\n      clearAutoPlayTimer();\n      if (state.playState.completed) return;\n      if (state.playState.currentIndex < state.playState.cards.length - 1) {\n        state.playState.currentIndex++;\n        updatePlayCard(true);\n      } else showCompletion();\n    }\n    function prevCard() {\n      clearAutoPlayTimer();\n      if (state.playState.completed) return;\n      if (state.playState.currentIndex > 0) { state.playState.currentIndex--; updatePlayCard(true); }\n    }\n    function markCard(status, skipNext = false) {\n      if (state.playState.completed) return;\n      const card = state.playState.cards[state.playState.currentIndex];\n      const deck = state.decks.find(item => item.id === state.playConfig.deckId);\n      const original = deck?.cards.find(item => item.id === card.id);\n      if (original) original.status = status;\n      card.status = status;\n      saveData();\n      if (!skipNext) {\n        if (state.playState.currentIndex < state.playState.cards.length - 1) nextCard();\n        else showCompletion();\n      }\n    }\n    function showCompletion() {\n      if (state.playState.completed) return;\n      clearAutoPlayTimer();\n      clearInterval(state.playState.typingInterval);\n      state.playState.completed = true;\n      state.playState.isFlipped = false;\n      const inner = document.getElementById(\"cardInner\");\n      inner.classList.remove(\"flipped\");\n      inner.innerHTML = `\n        <section class=\"card-face card-front completion-face\">\n          <i class=\"spark one\"></i><i class=\"spark two\"></i><i class=\"spark three\"></i><i class=\"spark four\"></i>\n          <div class=\"completion-badge\">✓</div>\n          <div class=\"completion-kicker\">Session complete</div>\n          <h2>Nice work!</h2>\n          <p>${state.playState.cards.length}枚のカードを最後まで学習しました。</p>\n          <div class=\"completion-actions\">\n            <button class=\"btn btn-secondary\" onclick=\"event.stopPropagation(); restartPlay()\">↻ もう一度</button>\n            <button class=\"btn btn-primary\" onclick=\"event.stopPropagation(); endPlay()\">一覧へ戻る</button>\n          </div>\n        </section>`;\n      document.getElementById(\"playProgressBar\").style.width = \"100%\";\n      document.querySelector(\".play-controls\").classList.add(\"completion-controls\");\n    }\n    function restartPlay() {\n      state.playState.currentIndex = 0;\n      state.playState.isFlipped = false;\n      state.playState.completed = false;\n      render();\n    }\n    function playAudio() {\n      const card = state.playState.cards[state.playState.currentIndex];\n      if (!card || !(\"speechSynthesis\" in window)) return;\n      const frontEnglish = state.playConfig.frontSide === \"en\";\n      const english = state.playState.isFlipped ? !frontEnglish : frontEnglish;\n      const text = english ? card.en : card.ja;\n      speechSynthesis.cancel();\n      const utterance = new SpeechSynthesisUtterance(text);\n      utterance.lang = english ? \"en-US\" : \"ja-JP\";\n      utterance.rate = .9;\n      speechSynthesis.speak(utterance);\n    }\n    function endPlay() {\n      speechSynthesis?.cancel();\n      clearInterval(state.playState.typingInterval);\n      clearAutoPlayTimer();\n      state.view = \"list\";\n      render();\n    }\n    function setupSwipeEvents() {\n      const card = document.getElementById(\"studyCard\");\n      let startX = 0, startY = 0, dx = 0, dy = 0, dragging = false;\n      const threshold = Math.min(innerWidth * .22, 190);\n      const point = event => event.touches?.[0] || event;\n      function start(event) {\n        if (state.playState.completed) return;\n        dragging = true;\n        clearAutoPlayTimer();\n        const p = point(event);\n        startX = p.clientX; startY = p.clientY;\n        card.classList.add(\"moving\");\n      }\n      function move(event) {\n        if (!dragging) return;\n        const p = point(event);\n        dx = p.clientX - startX; dy = p.clientY - startY;\n        if (Math.abs(dx) > Math.abs(dy) && event.cancelable) event.preventDefault();\n        card.style.transform = `translate(${dx}px, ${dy * .35}px) rotate(${dx * .035}deg)`;\n        document.getElementById(\"missLabel\").style.opacity = dx < 0 ? Math.min(Math.abs(dx) / threshold, 1) : 0;\n        document.getElementById(\"knowLabel\").style.opacity = dx > 0 ? Math.min(dx / threshold, 1) : 0;\n      }\n      function end() {\n        if (!dragging) return;\n        dragging = false;\n        card.classList.remove(\"moving\");\n        document.getElementById(\"missLabel\").style.opacity = 0;\n        document.getElementById(\"knowLabel\").style.opacity = 0;\n        if (Math.abs(dx) > threshold) {\n          const status = dx > 0 ? \"learned\" : \"unlearned\";\n          card.style.transform = `translateX(${dx > 0 ? innerWidth : -innerWidth}px) rotate(${dx > 0 ? 24 : -24}deg)`;\n          card.style.opacity = 0;\n          setTimeout(() => markCard(status), 260);\n        } else {\n          card.style.transform = \"\";\n          handleAutoPlayNext();\n        }\n        dx = dy = 0;\n      }\n      card.addEventListener(\"mousedown\", start);\n      card.addEventListener(\"touchstart\", start, { passive: true });\n      window.addEventListener(\"mousemove\", move);\n      window.addEventListener(\"touchmove\", move, { passive: false });\n      window.addEventListener(\"mouseup\", end);\n      window.addEventListener(\"touchend\", end);\n    }\n    document.addEventListener(\"keydown\", event => {\n      if (state.view !== \"play\") return;\n      if ([\" \", \"Enter\"].includes(event.key)) { event.preventDefault(); flipCard(); }\n      else if (event.key === \"ArrowRight\") nextCard();\n      else if (event.key === \"ArrowLeft\") prevCard();\n      else if (event.key === \"ArrowUp\" || event.key === \"1\") markCard(\"learned\");\n      else if (event.key === \"ArrowDown\" || event.key === \"2\") markCard(\"unlearned\");\n      else if ([\"s\",\"S\",\"p\",\"P\"].includes(event.key)) playAudio();\n      else if (event.key === \"Escape\") endPlay();\n    });\n    document.addEventListener(\"pointerdown\", event => {\n      document.querySelectorAll(\".theme-picker[open], .data-menu[open]\").forEach(menu => {\n        if (!menu.contains(event.target)) menu.removeAttribute(\"open\");\n      });\n    });\n\n    document.documentElement.dataset.theme = localStorage.getItem(THEME_KEY) || \"forest\";\n    loadData();\n    render();\n  </script>\n</body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not Found", { status: 404 });
    }
    return new Response(html, {
      headers: {
        "content-type": "text/html; charset=UTF-8",
        "cache-control": "no-cache"
      }
    });
  }
};
